{'name': 'Fleet', 'version': '0.1', 'sequence': 185, 'category': 'Human Resources/Fleet', 'website': 'https://uslbd.com', 'summary': 'Manage your fleet and track car costs', 'description': '\nVehicle, leasing, insurances, cost\n==================================\nWith this module, Odoo helps you managing all your vehicles, the\ncontracts associated to those vehicle as well as services, costs\nand many other features necessary to the management of your fleet\nof vehicle(s)\n\nMain Features\n-------------\n* Add vehicles to your fleet\n* Manage contracts for vehicles\n* Reminder when a contract reach its expiration date\n* Add services, odometer values for all vehicles\n* Show all costs associated to a vehicle or to a type of service\n* Analysis graph for costs\n', 'depends': ['base', 'mail'], 'data': ['security/fleet_security.xml', 'security/ir.model.access.csv', 'views/fleet_vehicle_model_views.xml', 'views/fleet_vehicle_views.xml', 'views/fleet_vehicle_cost_views.xml', 'views/fleet_board_view.xml', 'views/mail_activity_views.xml', 'views/res_config_settings_views.xml', 'views/fleet_vehicle_odometer_report.xml', 'data/fleet_cars_data.xml', 'data/fleet_data.xml', 'data/mail_message_subtype_data.xml', 'data/mail_activity_type_data.xml', 'wizard/fleet_vehicle_send_mail_views.xml'], 'demo': ['data/fleet_demo.xml'], 'installable': True, 'application': True, 'assets': {'web.assets_backend': ['fleet/static/src/**/*']}, 'author': 'UniSoft Systems Ltd.', 'license': 'LGPL-3'}